const workRecords = $input.all().map(item => item.json);
const clients = $('Get Client Details').all().map(item => item.json);

const now = new Date();
const year = now.getFullYear();
const month = now.getMonth();

const groups = {};

for (const work of workRecords) {
  const clientId = String(work.Client_ID || work.Client || '').trim();
  if (!clientId) continue;

  const client = clients.find(c =>
    String(c.Client_ID || c.Client || '').trim() === clientId
  );
  if (!client) continue;

  const rawDate = String(work.Date || '').trim();
  const dateMatch = rawDate.match(
    /^(\d{4})-(\d{1,2})-(\d{1,2})$/
  );

  let workDate;

  if (dateMatch) {
    workDate = new Date(
      Number(dateMatch[1]),
      Number(dateMatch[2]) - 1,
      Number(dateMatch[3])
    );
  } else {
    const shortMatch = rawDate.match(
      /^(\d{1,2})[-\s]([A-Za-z]{3})$/
    );

    if (shortMatch) {
      const monthNames = [
        'jan','feb','mar','apr','may','jun',
        'jul','aug','sep','oct','nov','dec'
      ];

      const workMonth = monthNames.indexOf(
        shortMatch[2].toLowerCase()
      );

      if (workMonth < 0) continue;

      workDate = new Date(
        year,
        workMonth,
        Number(shortMatch[1])
      );
    } else {
      continue;
    }
  }

  if (
    workDate.getFullYear() !== year ||
    workDate.getMonth() !== month
  ) continue;

  const qty = Number(work.Qty || 0);
  const rate = Number(work.Rate || 0);
  const amount = work.Amount !== undefined &&
                 work.Amount !== ''
    ? Number(work.Amount)
    : qty * rate;

  if (!Number.isFinite(amount) || amount < 0) continue;

  const workItem = {
    Date: rawDate,
    Project: work.Project || '',
    Work_Description: work.Work_Description || work.Work || 'CAD Work',
    Pricing_Type: work.Pricing_Type || 'Not Specified',
    Unit: work.Unit || 'Item',
    Qty: qty,
    Rate: rate,
    Amount: amount
  };

  // Remove exact duplicate rows only
  const uniqueKey = JSON.stringify(workItem);

  if (!groups[clientId]) {
    groups[clientId] = {
      Client_ID: clientId,
      Client_Name: client.Client_Name || clientId,
      Email: client.Email || '',
      Phone: client.Phone || '',
      Work_Items: [],
      _seen: new Set(),
      Total_Amount: 0
    };
  }

  if (groups[clientId]._seen.has(uniqueKey)) continue;

  groups[clientId]._seen.add(uniqueKey);
  groups[clientId].Work_Items.push(workItem);
  groups[clientId].Total_Amount += amount;
}

const billingPeriod =
  `${year}-${String(month + 1).padStart(2, '0')}`;

const result = Object.values(groups).map(client => {
  delete client._seen;

  return {
    json: {
      ...client,
      Total_Amount: Number(client.Total_Amount.toFixed(2)),
      Total_Work_Items: client.Work_Items.length,
      Billing_Period: billingPeriod
    }
  };
});

return result;

const reports = $('Calculate Client-Wise Billing')
  .all()
  .map(item => item.json);

if (reports.length === 0) {
  return [{
    json: {
      Telegram_Message:
        'MONTHLY CAD BILLING SUMMARY\n\nNo client invoices were generated.'
    }
  }];
}

const totalClients = reports.length;

const totalWorkItems = reports.reduce(
  (sum, report) => sum + Number(report.Total_Work_Items || 0),
  0
);

const totalAmount = reports.reduce(
  (sum, report) => sum + Number(report.Total_Amount || 0),
  0
);

const billingPeriod = reports[0].Billing_Period || 'Not available';

const clientLines = reports.map(report =>
  `• ${report.Client_Name} (${report.Client_ID}): ₹${Number(report.Total_Amount || 0).toFixed(2)}`
);

const message = [
  '📊 MONTHLY CAD BILLING SUMMARY',
  '',
  `📅 Billing Period: ${billingPeriod}`,
  `👥 Total Clients: ${totalClients}`,
  `📄 Invoices Generated: ${totalClients}`,
  `🛠 Total Work Items: ${totalWorkItems}`,
  `💰 Total Billing: ₹${totalAmount.toFixed(2)}`,
  '',
  'CLIENT-WISE BREAKDOWN',
  ...clientLines,
  '',
  '✅ All client invoices have been processed.'
].join('\n');

return [{
  json: {
    Billing_Period: billingPeriod,
    Total_Clients: totalClients,
    Total_PDFs: totalClients,
    Total_Work_Items: totalWorkItems,
    Total_Amount: Number(totalAmount.toFixed(2)),
    Telegram_Message: message
  }
}];

const clients = $input.all().map(item => item.json);

return clients.map(data => {
  const workItems = data.Work_Items || [];

  const items = workItems.map(work => {
    const qty = Number(work.Qty || 0);
    const amount = Number(work.Amount || 0);

    const quantity = qty > 0 ? qty : 1;
    const unitPrice = Number((amount / quantity).toFixed(2));

    return {
      description: [
  work.Project,
  work.Work_Description,
  work.Pricing_Type,
  work.Unit
]
.filter(value =>
  value &&
  String(value).trim().toLowerCase() !== 'not specified' &&
  String(value).trim().toLowerCase() !== 'item'
)
.join(' - '),
      quantity,
      unit_price: unitPrice
    };
  });

  return {
    json: {
      ...data,
      Invoice_Data: {
        from: {
          name: 'CAD Solutions'
        },
        to: {
          name: data.Client_Name,
          lines: [
            data.Phone ? `Phone: ${data.Phone}` : '',
            data.Email ? `Email: ${data.Email}` : ''
          ].filter(Boolean)
        },
        invoice_number: `INV-${data.Billing_Period}-${data.Client_ID}`,
        date: new Date().toISOString().slice(0, 10),
        currency: 'INR',
        items,
        notes: 'Thank you for your business.'
      },
      PDF_FileName: `${data.Client_ID}_${data.Billing_Period}_Invoice.pdf`
    }
  };
});
